package gen

import (
	"bytes"
	"errors"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"strconv"
	"strings"

	"github.com/castrowithcee/qatlas-connect/internal/provider/aws/awsquery"
)

// Header is the first line of every generated file. The generator overwrites only files that start with it.
const Header = "// Code generated by awsgen from the model extracts in gen/model and the curation tables in gen; DO NOT EDIT.\n"

// The generated files, relative to the provider package.
const (
	ToolsFile = "tools_gen.go"
	TestsFile = "tools_gen_test.go"
)

// Never in generated code: an AWS access key ID or a mail address. Literals of the first form are split.
var (
	accessKeyForm = regexp.MustCompile(`\b(AKIA|ASIA)([0-9A-Z]{16})\b`)
	mailForm      = regexp.MustCompile(`\b[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}\b`)
)

// exclusion is the exclude list of a table with tools, for the generated tests.
type exclusion struct {
	segment string
	actions []string
}

// Complete checks that every operation of the model is in exactly one list of the table and that the table
// names no operation the model lacks. A new model operation fails here instead of becoming a tool or being
// left out silently.
func Complete(t Table, m *Model) error {
	ops, err := m.Operations()
	if err != nil {
		return err
	}
	listed := map[string]bool{}
	for _, op := range t.Operations {
		listed[op.Operation] = true
	}
	for _, list := range [][]Omission{t.Exclude, t.Defer} {
		for _, o := range list {
			listed[o.Operation] = true
		}
	}
	var missing, unknown []string
	for _, op := range ops {
		if !listed[op] {
			missing = append(missing, op)
		}
		delete(listed, op)
	}
	for op := range listed {
		unknown = append(unknown, op)
	}
	slices.Sort(unknown)
	switch {
	case len(missing) > 0:
		return fmt.Errorf("table %s: model operations in neither operations, exclude nor defer: %s", t.Service, strings.Join(missing, ", "))
	case len(unknown) > 0:
		return fmt.Errorf("table %s: operations the model does not have: %s", t.Service, strings.Join(unknown, ", "))
	}
	return nil
}

// LoadTableModel reads the pinned extract of a table's service.
func LoadTableModel(modelDir string, p Pin, t Table) (*Model, error) {
	data, err := ReadExtract(modelDir, p, t.Service)
	if err != nil {
		return nil, err
	}
	return LoadModel(data)
}

// Render returns the generated files for the tables, read against the pinned extracts in modelDir.
func Render(modelDir string, tables []Table) (map[string][]byte, error) {
	p, err := LoadPin(modelDir)
	if err != nil {
		return nil, err
	}
	var tools []*tool
	var exclusions []exclusion
	for i := range tables {
		t := &tables[i]
		if err := t.Validate(); err != nil {
			return nil, err
		}
		m, err := LoadTableModel(modelDir, p, *t)
		if err != nil {
			return nil, fmt.Errorf("table %s: %w", t.Service, err)
		}
		if err := Complete(*t, m); err != nil {
			return nil, err
		}
		if m.Protocol != ProtocolQuery && len(t.Operations) > 0 {
			return nil, fmt.Errorf("table %s: %s operation %s cannot become a tool yet: tools are rendered for awsQuery only",
				t.Service, m.Protocol, t.Operations[0].Operation)
		}
		for _, op := range t.Operations {
			built, err := build(m, t, op)
			if err != nil {
				return nil, err
			}
			tools = append(tools, built)
		}
		if len(t.Operations) > 0 {
			var actions []string
			for _, o := range t.Exclude {
				actions = append(actions, o.Operation)
			}
			exclusions = append(exclusions, exclusion{t.Segment, actions})
		}
	}
	var code, tests bytes.Buffer
	renderTools(&code, tools)
	renderTests(&tests, tools, exclusions)
	out := map[string][]byte{}
	for name, src := range map[string][]byte{ToolsFile: code.Bytes(), TestsFile: tests.Bytes()} {
		formatted, err := format.Source(src)
		if err != nil {
			return nil, fmt.Errorf("%s does not format: %w", name, err)
		}
		if accessKeyForm.Match(formatted) || mailForm.Match(formatted) {
			return nil, fmt.Errorf("%s would hold an access key ID or a mail address", name)
		}
		out[name] = formatted
	}
	return out, nil
}

// Generate writes the generated files into outDir. It refuses to overwrite a file without the header, so a
// hand-written file is never touched.
func Generate(modelDir, outDir string) error {
	files, err := Render(modelDir, Tables)
	if err != nil {
		return err
	}
	for _, name := range []string{ToolsFile, TestsFile} {
		path := filepath.Join(outDir, name)
		prior, err := os.ReadFile(path)
		switch {
		case err == nil && !bytes.HasPrefix(prior, []byte(Header)):
			return fmt.Errorf("%s exists and is not a generated file", path)
		case err != nil && !errors.Is(err, os.ErrNotExist):
			return err
		}
		if err := os.WriteFile(path, files[name], 0o644); err != nil {
			return err
		}
	}
	return nil
}

func exclusionVar(segment string) string {
	return "excluded" + strings.ToUpper(strings.ReplaceAll(segment, "-", "")) + "Actions"
}

// lit renders a Go string literal. An access key ID is split in two, so no generated line holds one.
func lit(s string) string {
	if strings.Contains(s, `"`) && strconv.CanBackquote(s) && !strings.ContainsAny(s, "\x00\n\r\t") {
		return accessKeyForm.ReplaceAllString("`"+s+"`", "${1}` + `${2}")
	}
	return accessKeyForm.ReplaceAllString(strconv.Quote(s), `${1}" + "${2}`)
}

// schemaLit renders a schema with the region marker replaced by the regionSchema constant.
func schemaLit(s string) string {
	parts := strings.Split(s, regionMarker)
	out := make([]string, len(parts))
	for i, p := range parts {
		out[i] = lit(p)
	}
	return "json.RawMessage(" + strings.Join(out, " + regionSchema + ") + ")"
}

func stringSlice(list []string) string {
	if len(list) == 0 {
		return "nil"
	}
	q := make([]string, len(list))
	for i, s := range list {
		q[i] = lit(s)
	}
	return "[]string{" + strings.Join(q, ", ") + "}"
}

var (
	effectNames = map[string]string{"read": "EffectRead", "create": "EffectCreate", "update": "EffectUpdate",
		"delete": "EffectDelete", "execute": "EffectExecute"}
	idempotencyNames = map[string]string{"safe": "IdempotencySafe", "idempotent": "IdempotencyIdempotent",
		"non-idempotent": "IdempotencyNonIdempotent"}
	kindNames = map[awsquery.Kind]string{awsquery.KindString: "KindString", awsquery.KindInteger: "KindInteger",
		awsquery.KindFloat: "KindFloat", awsquery.KindBoolean: "KindBoolean", awsquery.KindTimestamp: "KindTimestamp",
		awsquery.KindBlob: "KindBlob", awsquery.KindStruct: "KindStruct", awsquery.KindList: "KindList",
		awsquery.KindMap: "KindMap"}
)

func renderTools(b *bytes.Buffer, tools []*tool) {
	b.WriteString(Header + `
package aws

import (
	"encoding/json"

	"github.com/castrowithcee/qatlas-connect/internal/capability"
	"github.com/castrowithcee/qatlas-connect/internal/provider/aws/awsquery"
	"github.com/castrowithcee/qatlas-connect/internal/provider/aws/endpoints"
)

// generatedSpecs are the tools of the curation tables, in table order.
var generatedSpecs = []toolSpec{
`)
	for _, t := range tools {
		confirmation := "ConfirmationNone"
		if t.op.Confirm {
			confirmation = "ConfirmationRequired"
		}
		fmt.Fprintf(b, "{\ndescriptor: capability.Descriptor{\nID: %s, Version: 1, Group: %s, Provider: Provider,\n", lit(t.id), lit(t.table.Segment))
		fmt.Fprintf(b, "Title: %s,\nDescription: %s + untrustedWarning,\nTags: %s,\n", lit(t.op.Title), lit(t.op.Description), stringSlice(t.op.Tags))
		fmt.Fprintf(b, "Risk: capability.Risk{Effect: capability.%s, Idempotency: capability.%s, Confirmation: capability.%s, OpenWorld: true, DataSensitivity: %s},\n",
			effectNames[t.op.Effect], idempotencyNames[t.op.Idempotency], confirmation, lit(t.op.DataSensitivity))
		if t.op.ListedOnly {
			b.WriteString("RequiresToolAllowList: true,\n")
		}
		fmt.Fprintf(b, "InputSchema: %s,\nOutputSchema: %s,\n", schemaLit(t.inputSchema), schemaLit(t.outputSchema))
		b.WriteString("Arguments: []capability.Argument{")
		for _, a := range t.args {
			if a.region {
				b.WriteString("regionArgument,\n")
				continue
			}
			req := ""
			if a.required {
				req = ", Required: true"
			}
			fmt.Fprintf(b, "{Name: %s, Description: %s%s},\n", lit(a.name), lit(a.description), req)
		}
		b.WriteString("},\nFields: []capability.Field{")
		for _, f := range t.fields {
			if f.region {
				b.WriteString("regionField,\n")
				continue
			}
			fmt.Fprintf(b, "{Name: %s, Description: %s},\n", lit(f.name), lit(f.description))
		}
		b.WriteString("},\n")
		if len(t.op.Examples) > 0 {
			b.WriteString("Examples: []capability.Example{")
			for _, e := range t.op.Examples {
				fmt.Fprintf(b, "{Description: %s, Arguments: json.RawMessage(%s)},\n", lit(e.Description), lit(e.Arguments))
			}
			b.WriteString("},\n")
		}
		b.WriteString("},\n")
		fmt.Fprintf(b, "service: endpoints.Service(%s), action: %s, version: %s, op: %s,\n", lit(t.table.Segment), lit(t.action), lit(t.version), lit(t.opName))
		fmt.Fprintf(b, "input: %s,\noutput: %s,\n", shapeLit(t.input), shapeLit(t.output))
		if t.pager != nil {
			fmt.Fprintf(b, "pager: &awsquery.Pager{TokenIn: %s, TokenOut: %s, Truncated: %s, SizeParam: %s, MaxSize: %d},\n",
				lit(t.pager.TokenIn), lit(t.pager.TokenOut), lit(t.pager.Truncated), lit(t.pager.SizeParam), t.pager.MaxSize)
		}
		if len(t.rules) > 0 {
			b.WriteString("rules: []outputRule{")
			for _, r := range t.rules {
				fmt.Fprintf(b, "{key: %s, form: %s, required: %t},", lit(r.key), lit(r.form), r.required)
			}
			b.WriteString("},\n")
		}
		fmt.Fprintf(b, "targetCheck: %s, targetArgs: %s, policyCheck: %s, policyArgs: %s,\n",
			lit(t.op.TargetCheck), stringSlice(t.targetArgs), lit(t.op.PolicyCheck), stringSlice(t.policyArgs))
		if t.op.AccountCheck {
			b.WriteString("accountCheck: true,\n")
		}
		if t.op.Truncated != "" {
			b.WriteString("truncated: true,\n")
		}
		b.WriteString("},\n")
	}
	b.WriteString("}\n")
}

func shapeLit(s *awsquery.Shape) string {
	parts := []string{"Kind: awsquery." + kindNames[s.Kind]}
	if len(s.Fields) > 0 {
		var fields []string
		for _, f := range s.Fields {
			field := fmt.Sprintf("{Key: %s, Name: %s, Shape: %s", lit(f.Key), lit(f.Name), shapeLit(f.Shape))
			if f.Flattened {
				field += ", Flattened: true"
			}
			if f.IdempotencyToken {
				field += ", IdempotencyToken: true"
			}
			fields = append(fields, field+"}")
		}
		parts = append(parts, "Fields: []awsquery.Field{"+strings.Join(fields, ", ")+"}")
	}
	if s.Elem != nil {
		parts = append(parts, "Elem: "+shapeLit(s.Elem))
	}
	for _, kv := range [][2]string{{"ElemName", s.ElemName}, {"KeyName", s.KeyName}, {"ValueName", s.ValueName}} {
		if kv[1] != "" {
			parts = append(parts, kv[0]+": "+lit(kv[1]))
		}
	}
	if s.MaxLen > 0 {
		parts = append(parts, "MaxLen: "+strconv.Itoa(s.MaxLen))
	}
	if s.MaxItems > 0 {
		parts = append(parts, "MaxItems: "+strconv.Itoa(s.MaxItems))
	}
	return "&awsquery.Shape{" + strings.Join(parts, ", ") + "}"
}

func renderTests(b *bytes.Buffer, tools []*tool, exclusions []exclusion) {
	b.WriteString(Header + "\npackage aws\n\nimport (\n\t\"slices\"\n\t\"testing\"\n)\n\n")
	for _, e := range exclusions {
		v := exclusionVar(e.segment)
		fmt.Fprintf(b, "// %s are the operations the %s table excludes; no tool may send one.\nvar %s = %s\n\n", v, e.segment, v, stringSlice(e.actions))
	}
	b.WriteString(`// generatedCases are the basic tests of the generated tools: arguments derived from the input schema,
// the form parameters they must encode to, and an answer derived from the output shape.
var generatedCases = []struct {
	tool, action, arguments, answer string
	form                            map[string]string
	token                           bool
	result                          []string
}{
`)
	for _, t := range tools {
		fmt.Fprintf(b, "{tool: %s, action: %s,\narguments: %s,\nanswer: %s,\nform: map[string]string{", lit(t.id), lit(t.action), lit(t.sampleArgs), lit(t.sampleAnswer))
		for _, k := range sortedKeys(t.sampleForm) {
			fmt.Fprintf(b, "%s: %s, ", lit(k), lit(t.sampleForm[k]))
		}
		fmt.Fprintf(b, "},\ntoken: %t, result: %s},\n", t.hasToken, stringSlice(t.resultKeys))
	}
	b.WriteString(`}

// Every generated tool sends its one action with exactly the encoded parameters and returns a result its
// output schema accepts.
func TestGeneratedTools(t *testing.T) {
	for _, c := range generatedCases {
		t.Run(c.tool, func(t *testing.T) {
			f := &fakeAWS{answer: func(r sent, _ int) reply {
				switch r.action {
				case c.action:
					return ok(c.answer)
				case "GetCallerIdentity":
					return ok(identityXML)
				}
				return reply{status: 500}
			}}
			e := newEnv(t, f, baseValues())
			text, err := e.invoke(c.tool, c.arguments)
			if err != nil {
				t.Fatalf("invoke: %v", err)
			}
			got := decodeResult(t, text)
			for _, key := range c.result {
				if _, ok := got[key]; !ok {
					t.Errorf("result lacks %s: %v", key, got)
				}
			}
			var call *sent
			for i := range f.requests {
				if f.requests[i].action == c.action {
					call = &f.requests[i]
				}
			}
			if call == nil {
				t.Fatalf("requests = %v, want %s", f.actions(), c.action)
			}
			want := len(c.form) + 2
			if c.token {
				want++
				if token, _ := got["client_token"].(string); token == "" || !formHolds(call.form, token) {
					t.Errorf("client_token = %v, not the token sent", got["client_token"])
				}
			}
			if len(call.form) != want {
				t.Errorf("form = %v, want exactly %v plus Action and Version", call.form, c.form)
			}
			for k, v := range c.form {
				if call.form.Get(k) != v {
					t.Errorf("form %s = %q, want %q", k, call.form.Get(k), v)
				}
			}
		})
	}
}

// No generated tool sends an operation its table excludes.
func TestGeneratedExclusionsAreNoTools(t *testing.T) {
	excluded := map[string][]string{
`)
	for _, e := range exclusions {
		fmt.Fprintf(b, "%s: %s,\n", lit(e.segment), exclusionVar(e.segment))
	}
	b.WriteString(`}
	for _, s := range generatedSpecs {
		if slices.Contains(excluded[string(s.service)], s.action) {
			t.Errorf("%s sends the excluded operation %s", s.descriptor.ID, s.action)
		}
	}
}
`)
}
